// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;

    function setUp() public {
        c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0));
    }

    // ICVXBooster stub on the test contract: report the pool as shutdown so the
    // onlyOperator gate is the ONLY thing exercised by depositAndStake.
    function poolInfo(uint256) external pure returns (address, address, address, address, address, bool) {
        return (address(0), address(0), address(0), address(0), address(0), true);
    }

    function deposit(uint256, uint256, bool) external pure returns (bool) {
        return true;
    }

    function withdraw(uint256, uint256) external pure returns (bool) {
        return true;
    }

    function depositAll(uint256, bool) external pure returns (bool) {
        return true;
    }

    function withdrawAll(uint256) external pure returns (bool) {
        return true;
    }

    function testFuzz_property(address newOperator, uint256 seed) public {
        // Rule: after the owner installs any address a as operator, the operator
        // gate admits an address x exactly when x == a. In particular, the
        // contract itself must never be admitted by the gate unless it was
        // explicitly installed as the operator.
        vm.prank(c.owner());
        c.setOperator(newOperator);

        // The gate is exercised by c.depositAndStake, whose only guard is
        // onlyOperator; the pool is shutdown so no external effects occur.
        vm.prank(address(c));
        bool admitted;
        try c.depositAndStake(seed) {
            admitted = true;
        } catch {
            admitted = false;
        }

        assertTrue(!admitted || newOperator == address(c));
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}
